INSERT INTO v2_vocabulary_examples(id,item_id,sense_id,kind,text,translation_zh,note_zh,readings_json,sort_order) VALUES
('35e1c-en-v001-ex1','35e1c-en-v001','35e1c-en-v001-s1','example','I have a peanut allergy.','我对花生过敏。','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v002-ex1','35e1c-en-v002','35e1c-en-v002-s1','example','Please let us know about any dietary restrictions.','如有任何饮食限制，请告诉我们。','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v003-ex1','35e1c-en-v003','35e1c-en-v003-s1','example','Does this sauce contain any dairy ingredients?','这个酱汁含乳制品配料吗？','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v004-ex1','35e1c-en-v004','35e1c-en-v004-s1','example','Is there a vegetarian option?','有素食选项吗？','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v005-ex1','35e1c-en-v005','35e1c-en-v005-s1','example','Could we have the bill, please?','请给我们账单好吗？','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v006-ex1','35e1c-en-v006','35e1c-en-v006-s1','example','Could I get a refill of water?','可以再给我加些水吗？','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v007-ex1','35e1c-en-v007','35e1c-en-v007-s1','example','I would like a refund, please.','我想申请退款。','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v008-ex1','35e1c-en-v008','35e1c-en-v008-s1','example','Can I exchange this for a larger size?','我可以把这个换成大一号的吗？','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v009-ex1','35e1c-en-v009','35e1c-en-v009-s1','example','The rice is in aisle five.','米在第五条通道。','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v010-ex1','35e1c-en-v010','35e1c-en-v010-s1','example','Please pay at the checkout counter.','请在结账台付款。','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v011-ex1','35e1c-en-v011','35e1c-en-v011-s1','example','Do you accept contactless payment?','你们接受非接触式支付吗？','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v012-ex1','35e1c-en-v012','35e1c-en-v012-s1','example','The charger is faulty.','这个充电器有故障。','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v013-ex1','35e1c-en-v013','35e1c-en-v013-s1','example','What is your return policy?','你们的退货政策是什么？','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v014-ex1','35e1c-en-v014','35e1c-en-v014-s1','example','The item must be in its original packaging.','商品必须保留原包装。','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v015-ex1','35e1c-en-v015','35e1c-en-v015-s1','example','We can offer store credit instead of a cash refund.','我们可以提供商店代金余额，而不是现金退款。','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v016-ex1','35e1c-en-v016','35e1c-en-v016-s1','example','That model is currently out of stock.','那个型号目前缺货。','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v017-ex1','35e1c-en-v017','35e1c-en-v017-s1','example','I have had a fever since last night.','我从昨晚开始发烧。','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v018-ex1','35e1c-en-v018','35e1c-en-v018-s1','example','I have a dry cough.','我干咳。','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v019-ex1','35e1c-en-v019','35e1c-en-v019-s1','example','I feel dizzy when I stand up.','我站起来时会头晕。','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v020-ex1','35e1c-en-v020','35e1c-en-v020-s1','example','Is there a pharmacy nearby?','附近有药房吗？','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v021-ex1','35e1c-en-v021','35e1c-en-v021-s1','example','You need a prescription for this medicine.','这种药需要处方。','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v022-ex1','35e1c-en-v022','35e1c-en-v022-s1','example','When did the symptoms start?','症状什么时候开始的？','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v023-ex1','35e1c-en-v023','35e1c-en-v023-s1','example','I have a sore throat and a cough.','我喉咙痛，还有咳嗽。','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v024-ex1','35e1c-en-v024','35e1c-en-v024-s1','example','Take one painkiller after food.','饭后服一片止痛药。','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v025-ex1','35e1c-en-v025','35e1c-en-v025-s1','example','Please follow the dosage on the label.','请按标签上的剂量服用。','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v026-ex1','35e1c-en-v026','35e1c-en-v026-s1','example','This medicine may cause a mild side effect.','这种药可能会引起轻微副作用。','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v027-ex1','35e1c-en-v027','35e1c-en-v027-s1','example','There is some swelling around my ankle.','我的脚踝周围有些肿。','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v028-ex1','35e1c-en-v028','35e1c-en-v028-s1','example','The rash appeared this morning.','皮疹今天早上出现了。','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v029-ex1','35e1c-en-v029','35e1c-en-v029-s1','example','Is there an afternoon time slot available?','下午有可预约时段吗？','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v030-ex1','35e1c-en-v030','35e1c-en-v030-s1','example','Could we reschedule the appointment for Friday?','我们可以把预约改到周五吗？','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v031-ex1','35e1c-en-v031','35e1c-en-v031-s1','example','Could you check the doctor’s availability?','你能查一下医生有空的时间吗？','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v032-ex1','35e1c-en-v032','35e1c-en-v032-s1','example','You will receive a confirmation by email.','你会通过邮件收到确认信息。','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v033-ex1','35e1c-en-v033','35e1c-en-v033-s1','example','We are fully booked on Monday.','我们周一已经约满了。','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v034-ex1','35e1c-en-v034','35e1c-en-v034-s1','example','I reported the leak to my landlord.','我把漏水问题告诉了房东。','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v035-ex1','35e1c-en-v035','35e1c-en-v035-s1','example','The tenant is responsible for keeping the room clean.','租客负责保持房间整洁。','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v036-ex1','35e1c-en-v036','35e1c-en-v036-s1','example','The rent is due on the first of each month.','房租每月一号到期。','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v037-ex1','35e1c-en-v037','35e1c-en-v037-s1','example','The deposit is equal to four weeks’ rent.','押金相当于四周房租。','经语义范围、搭配/助词与编辑复核。','[]','1'),
('35e1c-en-v038-ex1','35e1c-en-v038','35e1c-en-v038-s1','example','Please read the lease before signing it.','签字前请阅读租约。','经语义范围、搭配/助词与编辑复核。','[]','1'),
