INSERT INTO v2_grammar_points(id,language,slug,title_zh,form_name,level,core_zh,purpose_zh,formula,when_zh,mistakes_zh,nuance_zh,register,usage_zh,publication_state,sort_order) VALUES
('35e1c-en-negation-short-answers','en','negation-short-answers','一般现在时否定与简短回答','do/does not; Yes, ... do. / No, ... do not.','1','用 do/does 承担一般现在时的否定和问答。','否定事实、习惯或需要，并作自然简答。','subject + do/does not + base verb; Do/Does ...?','谈论现在的习惯、事实或需要时。','第三人称否定后动词不用 -s；简答不能只机械重复主句。','be 动词不用 do；回答常用缩略形式。','neutral','系统/对比型 canonical grammar；保留 required/support/exposure 区分。','published','1406'),
('35e1c-en-past-questions-negatives','en','past-questions-negatives','一般过去时问句与否定','Did ...? / did not + base verb','2','did 标记过去后，实义动词回到原形。','询问或否定已经结束的事情。','Did + subject + base verb?; subject + did not + base verb','核实过去发生的预约、付款或故障。','不要写 did went / did not received。','be 动词过去式使用 was/were，不使用 did。','neutral','系统/对比型 canonical grammar；保留 required/support/exposure 区分。','published','1407'),
('35e1c-en-article-system','en','article-system','冠词系统：a/an、the 与零冠词','a/an; the; zero article','1','冠词表示名词是否可数、是否首次出现以及双方是否能识别。','自然引入和再次指称人物或事物。','a/an + singular count noun; the + identifiable noun','介绍一个新对象、回指或谈论类别时。','单数可数名词通常不能裸用；不可数名词不随意加 a。','零冠词常用于复数/不可数的泛指。','neutral','系统/对比型 canonical grammar；保留 required/support/exposure 区分。','published','1408'),
('35e1c-en-some-any','en','some-any','some / any 与可数性','some / any + plural or non-count noun','2','some 常用于肯定与主动提供，any 常用于疑问和否定。','谈论不确定数量。','some/any + plural count noun or non-count noun','购物、点餐和询问库存时。','不要把不可数名词机械变复数。','期待肯定回答的礼貌请求中常用 some。','neutral','系统/对比型 canonical grammar；保留 required/support/exposure 区分。','published','1409'),
('35e1c-en-should-advice','en','should-advice','should / should not 表建议','should (not) + base verb','2','should 给出建议，不等于强制命令。','提供或询问适度建议。','subject + should/should not + base verb','健康、出行和处理问题时。','should 后不用 to，也不随人称变化。','语气通常比 must 柔和。','neutral','系统/对比型 canonical grammar；保留 required/support/exposure 区分。','published','1410'),
('35e1c-en-obligation-contrast','en','obligation-contrast','must / have to / do not have to 对比','must; have to; do not have to','3','区分说话者强调的义务、外部规定和没有必要。','说明规则、职责与可选事项。','must/have to + base verb; do not have to + base verb','工作、租房、旅行规定中。','do not have to 表示“不必”，不是“禁止”。','must not 表禁止；have to 更常指外部要求。','neutral','系统/对比型 canonical grammar；保留 required/support/exposure 区分。','published','1411'),
('35e1c-en-first-conditional','en','first-conditional','第一条件句','If + present, will/can/imperative','3','用现实可能的条件连接未来结果或行动。','讨论可行的安排与后果。','if + present simple, will/can + base verb','预约、行程和排障时。','if 从句中通常不用 will 表普通未来。','主句可用 will、can 或祈使句。','neutral','系统/对比型 canonical grammar；保留 required/support/exposure 区分。','published','1412'),
('35e1c-en-future-arrangements','en','future-arrangements','现在进行时表示已安排的将来','be + V-ing + future time','3','现在进行时可表示已经约定或落实的近期安排。','说明日程中已确定的未来活动。','subject + be + V-ing + future time','预约、面试、出行和工作排班。','需要未来时间语境；不要和正在发生混淆。','通常比 be going to 更强调已有安排。','neutral','系统/对比型 canonical grammar；保留 required/support/exposure 区分。','published','1413'),
('35e1c-en-perfect-vs-past','en','perfect-vs-past','现在完成时与一般过去时对比','have + participle vs past form','4','现在完成时连接现在；一般过去时把事件放在已结束的过去。','准确报告经历、结果或具体过去时间。','have/has + past participle; simple past','汇报进展、故障和旅行经历时。','带 yesterday/last week 等已结束时间通常不用现在完成时。','结果仍相关时常用现在完成时。','neutral','系统/对比型 canonical grammar；保留 required/support/exposure 区分。','published','1414'),
('35e1c-en-reported-statements','en','reported-statements','转述陈述与信息','said/told + (that) clause','4','用 said 或 told 转述他人的信息，并明确接收者。','在工作和服务场景中传递消息。','say (that) + clause; tell + person + (that) + clause','转达安排、说明或决定时。','tell 后通常要有人作宾语；不要写 said me。','时间明确且内容仍有效时不必机械回移时态。','neutral','系统/对比型 canonical grammar；保留 required/support/exposure 区分。','published','1415'),
('35e1c-ja-movement-particles','ja','movement-particles','移動の「に・へ」と動作場所の「で」','場所に／へ行く；場所で動作する','1','に・へ表示移动目的地，で表示动作发生处。','区分“去哪里”和“在哪里做什么”。','destination + に/へ + 移動動詞；place + で + 動作動詞','问路、交通和日常活动。','「駅で行きます」不能表示去车站。','へ偏方向，に偏到达点；很多移动语境可互换。','neutral','系统/对比型 canonical grammar；保留 required/support/exposure 区分。','published','1416'),
('35e1c-ja-kara-made-range','ja','kara-made-range','起点と終点の「から・まで」','N から N まで','1','から标起点，まで标终点，可以只用其中之一。','表达时间或空间范围。','start + から；end + まで','营业时间、路线和工作时间。','まで不是“到达”的动词助词。','强调截止期限时也可用まで。','neutral','系统/对比型 canonical grammar；保留 required/support/exposure 区分。','published','1417'),
('35e1c-ja-adjective-tense','ja','adjective-tense','い形容詞・な形容詞の否定と過去','〜くない／〜かった；〜ではない／〜だった','2','两类形容词的否定和过去活用不同。','描述过去状态或否定性质。','い→くない/かった；な→ではない/だった','评价房间、食物、身体状态。','な形容词不能变成〜くない；いい的过去是よかった。','礼貌体可用〜くありません、〜ではありません。','neutral','系统/对比型 canonical grammar；保留 required/support/exposure 区分。','published','1418'),
('35e1c-ja-plain-tense-system','ja','plain-tense-system','普通形の肯定・否定・過去','辞書形／ない形／た形／なかった形','2','普通体用四个基本形式表达非过去/过去与肯定/否定。','在关系近的交流及从句中准确变化。','Vる・Vない・Vた・Vなかった','朋友会话以及と思う、ので等前面。','不要把ます和普通形词尾混合。','普通体不等于粗鲁，是否合适取决于关系和场景。','neutral','系统/对比型 canonical grammar；保留 required/support/exposure 区分。','published','1419'),
('35e1c-ja-te-sequence','ja','te-sequence','て形で動作をつなぐ','Vて、V','2','て形按语境连接先后或并列动作。','简洁说明一连串日常行动。','verb て-form + clause','说明路线、手续和工作流程。','て形本身不总表示严格先后；需要时加それから。','同一主语的一连串动作尤其自然。','neutral','系统/对比型 canonical grammar；保留 required/support/exposure 区分。','published','1420'),
('35e1c-ja-permission-prohibition','ja','permission-prohibition','〜てもいい・〜てはいけない','Vてもいい；Vてはいけない','2','一个表示许可，一个表示禁止。','询问许可或说明规则。','て-form + もいい／はいけない','住宿、职场和公共场所。','〜なくてもいい是“不必”，不要当成禁止。','口语禁止也常用〜てはだめ。','neutral','系统/对比型 canonical grammar；保留 required/support/exposure 区分。','published','1421'),
('35e1c-ja-counter-system','ja','counter-system','助数詞：人・本・枚・個・つ','number + counter','2','根据人或物的形状/类别选择助数词，并注意读音变化。','在购物、餐厅和预约中准确计数。','人: ひとり/ふたり；本・枚・個・つ','购买、人数、份数和物品数量。','不要对所有东西都只用個。','不知道专用量词时，つ可数部分一般物品到十。','neutral','系统/对比型 canonical grammar；保留 required/support/exposure 区分。','published','1422'),
('35e1c-ja-obligation-contrast','ja','obligation-contrast','〜なければならない・〜なくてもいい','Vなければならない；Vなくてもいい','3','区分必须做和不必做。','说明义务、规则与可选事项。','ない形去い + ければならない／くてもいい','工作、手续、住宿和健康建议。','〜なくてもいい不是“不能做”。','口语中义务常缩略为〜なきゃ。','neutral','系统/对比型 canonical grammar；保留 required/support/exposure 区分。','published','1423'),
('35e1c-ja-kara-node-contrast','ja','kara-node-contrast','理由の「から・ので」','plain/polite clause + から／ので','3','两者都说明理由；ので通常更柔和客观。','解释原因并为请求或变更铺垫。','clause + から／ので、result','请假、改期、拒绝与说明问题。','名词/な形容词接ので时用なので。','から较直接；在服务和职场请求中ので常更缓和。','neutral','系统/对比型 canonical grammar；保留 required/support/exposure 区分。','published','1424'),
('35e1c-ja-comparison-system','ja','comparison-system','〜より・〜ほうがで比べる','AよりBのほうが adjective','3','より标比较基准，ほうが标在该维度更突出的一方。','比较商品、时间和选择。','A より B のほうが + predicate','购物、建议和选择方案时。','不要把比较方向说反。','只说Bのほうが也可承接上文比较。','neutral','系统/对比型 canonical grammar；保留 required/support/exposure 区分。','published','1425'),
('35e1c-ja-giving-receiving','ja','giving-receiving','あげる・くれる・もらう','giver が receiver に N/Vて + verb','3','根据叙述视点选择给予、为己方做或接受。','表达帮助、恩惠和物品往来。','AがBにあげる；Aが私にくれる；私はAにもらう','同事协作、朋友帮助和服务。','くれる的接受方通常是说话者一方。','て形组合能表达“为某人做某事”。','neutral','系统/对比型 canonical grammar；保留 required/support/exposure 区分。','published','1426'),
('35e1c-ja-condition-contrast','ja','condition-contrast','条件の「なら・たら・ば・と」','N/普通形なら；た形ら；ば形；辞書形と','4','根据前提来源、时序和结果性质选择条件形式。','协商方案、说明规则或自然结果。','なら/たら/ば/と + result','出行变更、排障、建议和规则。','命令、意志句通常不接表示自然结果的と。','なら承接话题；たら灵活；ば重条件；と表规律或自动结果。','neutral','系统/对比型 canonical grammar；保留 required/support/exposure 区分。','published','1427'),
('35e1c-ja-sentence-final-softeners','ja','sentence-final-softeners','終助詞「ね・よ・かな」','clause + ね／よ／かな','3','句末助词管理共享信息、告知和自问语气。','让确认、提醒和犹豫更自然。','sentence + particle','日常确认、提出看法和思考选择时。','よ连续使用会显得强硬；かな不宜用于正式请求。','ね邀请对方确认；よ提供新信息；かな表示自问。','neutral','系统/对比型 canonical grammar；保留 required/support/exposure 区分。','published','1428'),
('35e1c-ja-workplace-register','ja','workplace-register','職場の敬体・尊敬語・謙譲語切り替え','です/ます；お/ご〜になる；お/ご〜する','4','根据行为主体与关系距离，区分普通礼貌、抬高对方和压低己方。','在汇报、联系、接待中选择合适语域。','polite / honorific / humble by actor','职场内部、客户接待和正式联络。','不是把所有动词都机械加お；先判断谁做动作。','同事内部通常以です/ます为基础，面对客户再用必要敬语。','neutral','系统/对比型 canonical grammar；保留 required/support/exposure 区分。','published','1429'),
('35e1c-ja-explanatory-nodesu','ja','explanatory-nodesu','〜んです・〜んですがの説明と前置き','plain + んです／んですが','3','补充背景或温和地引出请求和问题。','解释情况、求助或开启协商。','V/い-adj plain + んです；N/な-adj + なんです','服务、医疗、租房和职场咨询。','不能把名词直接接んです，需用なんです。','んですが常把具体请求留给后句，语气更柔和。','neutral','系统/对比型 canonical grammar；保留 required/support/exposure 区分。','published','1430'),
('35e1c-ja-experience-system','ja','experience-system','〜たことがあるで経験を話す','Vた + ことがある','3','表示截至现在曾有过某种经历。','询问或分享人生经验。','past plain verb + ことがある','旅行、工作和社交经历。','具体一次的过去事件通常直接用た形，不用ことがある。','否定是〜たことがない。','neutral','系统/对比型 canonical grammar；保留 required/support/exposure 区分。','published','1431');
