INSERT INTO v2_grammar_examples(id,grammar_id,language,text,translation_zh,explanation_zh,ipa,readings_json,source_expression_id,sort_order) VALUES
('35e1c-ja-movement-particles-ex1','35e1c-ja-movement-particles','ja','駅に行きます。','去车站。','直接实例化本语法的核心形式或必要对比。',NULL,'[{"text":"駅に行きます。"}]',NULL,'1'),
('35e1c-ja-movement-particles-ex2','35e1c-ja-movement-particles','ja','駅へ向かっています。','正在往车站去。','直接实例化本语法的核心形式或必要对比。',NULL,'[{"text":"駅へ向かっています。"}]',NULL,'2'),
('35e1c-ja-movement-particles-ex3','35e1c-ja-movement-particles','ja','駅で友達を待ちます。','在车站等朋友。','直接实例化本语法的核心形式或必要对比。',NULL,'[{"text":"駅で友達を待ちます。"}]',NULL,'3'),
('35e1c-ja-movement-particles-ex4','35e1c-ja-movement-particles','ja','ホテルで朝食を食べました。','在酒店吃了早餐。','直接实例化本语法的核心形式或必要对比。',NULL,'[{"text":"ホテルで朝食を食べました。"}]',NULL,'4'),
('35e1c-ja-kara-made-range-ex1','35e1c-ja-kara-made-range','ja','九時から働きます。','从九点开始工作。','直接实例化本语法的核心形式或必要对比。',NULL,'[{"text":"九時から働きます。"}]',NULL,'1'),
('35e1c-ja-kara-made-range-ex2','35e1c-ja-kara-made-range','ja','店は五時までです。','店营业到五点。','直接实例化本语法的核心形式或必要对比。',NULL,'[{"text":"店は五時までです。"}]',NULL,'2'),
('35e1c-ja-kara-made-range-ex3','35e1c-ja-kara-made-range','ja','駅からホテルまで歩きました。','从车站走到酒店。','直接实例化本语法的核心形式或必要对比。',NULL,'[{"text":"駅からホテルまで歩きました。"}]',NULL,'3'),
('35e1c-ja-kara-made-range-ex4','35e1c-ja-kara-made-range','ja','金曜日までに提出してください。','请在周五之前提交。','直接实例化本语法的核心形式或必要对比。',NULL,'[{"text":"金曜日までに提出してください。"}]',NULL,'4'),
('35e1c-ja-adjective-tense-ex1','35e1c-ja-adjective-tense','ja','部屋は広くないです。','房间不宽敞。','直接实例化本语法的核心形式或必要对比。',NULL,'[{"text":"部屋は広くないです。"}]',NULL,'1'),
('35e1c-ja-adjective-tense-ex2','35e1c-ja-adjective-tense','ja','昨日は寒かったです。','昨天很冷。','直接实例化本语法的核心形式或必要对比。',NULL,'[{"text":"昨日は寒かったです。"}]',NULL,'2'),
('35e1c-ja-adjective-tense-ex3','35e1c-ja-adjective-tense','ja','この辺は静かではありません。','这一带不安静。','直接实例化本语法的核心形式或必要对比。',NULL,'[{"text":"この辺は静かではありません。"}]',NULL,'3'),
('35e1c-ja-adjective-tense-ex4','35e1c-ja-adjective-tense','ja','ホテルは便利でした。','酒店很方便。','直接实例化本语法的核心形式或必要对比。',NULL,'[{"text":"ホテルは便利でした。"}]',NULL,'4'),
